import{_ as o,o as t,c as d,ag as a}from"./chunks/framework.CPvOxTBX.js";const g=JSON.parse('{"title":"Dictionary Link Schemes: A Deep Dive","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dictionary-link-schemes.md","filePath":"guide/dictionary-link-schemes.md","lastUpdated":1793489430000}'),r={name:"guide/dictionary-link-schemes.md"};function c(n,e,i,s,l,h){return t(),d("div",null,e[0]||(e[0]=[a('<h1 id="dictionary-link-schemes-a-deep-dive" tabindex="-1">Dictionary Link Schemes: A Deep Dive <a class="header-anchor" href="#dictionary-link-schemes-a-deep-dive" aria-label="Permalink to &quot;Dictionary Link Schemes: A Deep Dive&quot;">​</a></h1><p>Ciyue supports the link conventions that MDict, Babylon and GoldenDict dictionaries already use. The <a href="./dictionary-links.html">Dictionary Links</a> page lists the shapes you can <em>write</em>. This page explains <em>why</em> those rules exist — by looking at how GoldenDict-ng, MDict and Babylon actually treat them, where Ciyue goes further, and what a compatible reader must (and must not) support.</p><h2 id="two-layers-of-schemes" tabindex="-1">Two layers of schemes <a class="header-anchor" href="#two-layers-of-schemes" aria-label="Permalink to &quot;Two layers of schemes&quot;">​</a></h2><p>Every link scheme in this ecosystem falls into one of two layers.</p><p><strong>Authored into dictionary files</strong> — what dictionary makers actually write:</p><table tabindex="0"><thead><tr><th>Scheme</th><th>Origin</th><th>Meaning</th></tr></thead><tbody><tr><td><code>entry://word</code></td><td>MDX / MDict</td><td>jump to entry <code>word</code></td></tr><tr><td><code>bword://word</code></td><td>Babylon <code>.bgl</code></td><td>same as <code>entry://word</code></td></tr><tr><td><code>gdlookup://localhost/word</code></td><td>GoldenDict-ng</td><td>cross-dictionary lookup of <code>word</code></td></tr><tr><td><code>sound://file</code></td><td>MDX / Babylon</td><td>play audio <code>file</code></td></tr></tbody></table><p><strong>Generated at runtime by GoldenDict-ng&#39;s loaders</strong> — never present in a source file: <code>gdau</code>, <code>bres</code>, <code>gico</code>, <code>gdprg</code>, <code>gdtts</code>, <code>gdinternal</code>.</p><p>GoldenDict-ng registers <em>both</em> <code>bword</code> and <code>entry</code> (and <code>gdlookup</code>) as custom URL schemes and treats them identically: it extracts the headword and looks it up across all loaded dictionaries (<code>main.cc</code> registers the schemes; <code>utils.hh</code> resolves <code>bword</code>/<code>entry</code>/<code>gdlookup</code> the same way). That is why a single reader can follow either spelling.</p><h3 id="cross-format-mixing-only-works-in-goldendict-ng" tabindex="-1">Cross-format mixing only works in GoldenDict-ng <a class="header-anchor" href="#cross-format-mixing-only-works-in-goldendict-ng" aria-label="Permalink to &quot;Cross-format mixing only works in GoldenDict-ng&quot;">​</a></h3><p>Because each loader only rewrites <em>its own</em> scheme, you can build hybrids that only GoldenDict-ng understands:</p><ul><li>An <strong>MDX that contains <code>bword://word</code></strong>: the MDX loader&#39;s link rewriter only knows <code>entry://</code> and <code>sound://</code>; it leaves <code>bword://</code> untouched, and the global <code>bword</code> scheme handler picks it up. Original MDict never sees <code>bword:</code> and cannot follow it.</li><li>A <strong>Babylon <code>.bgl</code> that contains <code>entry://word</code></strong>: the BGL loader only normalizes <code>bword:</code>, so <code>entry://</code> passes through to the global handler. Original Babylon does not understand <code>entry://</code>.</li></ul><p>Even for the &quot;standard&quot; spelling the behavior differs: GoldenDict-ng rewrites <code>entry://word</code> into <code>gdlookup://localhost/word</code>, a lookup that spans <strong>all</strong> loaded dictionaries, whereas MDict&#39;s own <code>entry://</code> only jumps <strong>within the current <code>.mdx</code></strong>.</p><h2 id="sound-and-the-stardict-conversion-trap" tabindex="-1"><code>sound://</code> and the StarDict conversion trap <a class="header-anchor" href="#sound-and-the-stardict-conversion-trap" aria-label="Permalink to &quot;`sound://` and the StarDict conversion trap&quot;">​</a></h2><p><code>sound://</code> is the MDX/Babylon audio convention. In GoldenDict-ng <strong>only the MDX loader</strong> rewrites <code>sound://</code> → <code>gdau://</code> (the internal audio scheme). The StarDict loader does <em>not</em> rewrite <code>sound://</code>: its link rewriter passes any <code>a</code> link that contains a <code>:</code> through untouched, and its <code>&lt;audio&gt;</code> handler only converts sources that have <strong>no</strong> <code>://</code> in them. Since <code>sound</code> is not a registered scheme, a <code>sound://</code> link surviving into a StarDict file is simply a dead link.</p><p>This is exactly why converting an MDX to StarDict with a tool that keeps the MDX-style <code>sound://</code> links makes the audio stop working: the audio tag is no longer rewritten. By contrast, <code>&lt;audio src=&quot;relative.wav&quot;&gt;</code> (no <code>://</code>) <em>does</em> work in the StarDict loader, because it gets rewritten into <code>gdau://</code>.</p><p>Practical guidance:</p><ul><li>If a dictionary has MDX audio, just load the original MDX — it is natively supported and <code>sound://</code> is handled correctly.</li><li>If you must produce StarDict, make the converter emit StarDict-native relative resources (a relative <code>&lt;audio&gt;</code> source, or the <code>snd:</code> resource form) rather than MDX-style <code>sound://</code> links.</li></ul><h2 id="gdlookup-localhost-word-—-the-stable-cross-reference" tabindex="-1"><code>gdlookup://localhost/word</code> — the stable cross-reference <a class="header-anchor" href="#gdlookup-localhost-word-—-the-stable-cross-reference" aria-label="Permalink to &quot;`gdlookup://localhost/word` — the stable cross-reference&quot;">​</a></h2><p>Unlike <code>gdau://</code> (below), this form is <strong>stable and portable</strong>:</p><ul><li><code>localhost</code> is a hard-coded constant in GoldenDict-ng&#39;s scheme handling; the meaningful part is the headword in the path.</li><li>Resolution looks the word up across all loaded dictionaries, so moving, renaming, or copying the dictionary file does not matter.</li><li>It is content-addressed, not location-addressed, which means it can be hand-authored — and indeed appears in real dictionaries (including some made by the Ciyue author).</li></ul><p>Ciyue supports it: its entry-URL check accepts <code>gdlookup</code> with host <code>localhost</code>.</p><h3 id="why-localhost-at-all" tabindex="-1">Why <code>localhost</code> at all? <a class="header-anchor" href="#why-localhost-at-all" aria-label="Permalink to &quot;Why `localhost` at all?&quot;">​</a></h3><p>The original GoldenDict commit <code>e4e5a969</code> (Konstantin Isakov, the GoldenDict author) says it plainly:</p><blockquote><p>Switch to <code>gdlookup://localhost/word</code> scheme in dsl word references. This fixes cases with uppercased/capitalized words.</p></blockquote><p>A URL <strong>host</strong> is always folded to lower case by the parser; a <strong>path</strong> is not. <code>gdlookup://Word</code> would arrive as <code>word</code>, breaking case-sensitive lookups. The dummy authority <code>localhost</code> exists for one reason: to push the headword into the <strong>path</strong>, where its case is preserved.</p><p>Ciyue rediscovered the same bug and fixed it in the same way. Earlier Ciyue carried the headword in the host, so <code>entry://Abend</code> arrived as <code>abend</code>, and <code>entry://A.D.</code> / <code>entry://tag:sumeru</code> were parsed as <code>host:port</code> and resolved to nothing (the <code>:</code> in <code>tag:sumeru</code> is read as the port separator — a pitfall first hit while building a Genshin dictionary, where links like <code>entry://tag:sumeru</code> are used). The fix moves the word into the path as <code>gdlookup://localhost/&lt;percent-encoded&gt;</code>, which is exactly the shape GoldenDict uses, for exactly the same reason. Those cases are now permanent regression tests in Ciyue.</p><h2 id="gdau-—-why-a-compatible-reader-can-ignore-it" tabindex="-1"><code>gdau://</code> — why a compatible reader can ignore it <a class="header-anchor" href="#gdau-—-why-a-compatible-reader-can-ignore-it" aria-label="Permalink to &quot;`gdau://` — why a compatible reader can ignore it&quot;">​</a></h2><p><code>gdau://&lt;id&gt;/file</code> looks similar to <code>gdlookup://</code> but is fundamentally different:</p><ul><li><code>&lt;id&gt;</code> is an <strong>MD5 of the dictionary&#39;s absolute file path(s)</strong> (<code>makeDictionaryId</code> in GoldenDict-ng). It changes if the file moves or the machine changes.</li><li><code>&lt;file&gt;</code> is the resource name within that dictionary.</li><li>It is resolved by looking the dictionary up <em>by that id hash</em>, then fetching the resource.</li></ul><p>Because the id is a path-derived hash, <code>gdau://</code> is <strong>not portable and not authorable</strong> — you cannot write a <code>gdau://</code> link that works anywhere but the machine/session that produced it. And it is only ever <em>emitted at runtime</em> by GoldenDict-ng&#39;s loaders (MDX rewrites <code>sound://</code> → <code>gdau://</code>; StarDict rewrites <code>&lt;audio src=&quot;rel&quot;&gt;</code> → <code>gdau://</code>). No source dictionary file contains <code>gdau://</code>.</p><p>So a third-party reader that wants to be a superset of GoldenDict-ng should support the <em>authored</em> layer (<code>entry</code>, <code>bword</code>, <code>gdlookup://localhost/…</code>, <code>sound://</code>) and need not — and should not expect to receive — <code>gdau://</code>. Ciyue uses its own audio plumbing (<code>sound://</code> plus a local HTTP server serving the dictionary&#39;s <code>res/</code> and <code>.mdd</code> resources) instead.</p><h2 id="handling-where-ciyue-is-a-strict-superset" tabindex="-1"><code>#</code> handling: where Ciyue is a strict superset <a class="header-anchor" href="#handling-where-ciyue-is-a-strict-superset" aria-label="Permalink to &quot;`#` handling: where Ciyue is a strict superset&quot;">​</a></h2><p>For the <strong>anchor</strong> (scroll-to) part, GoldenDict-ng and Ciyue are equivalent: both carry it as a <code>?gdanchor=</code> query parameter rather than a <code>#</code> fragment, precisely so the fragment is not swallowed before the handler sees it.</p><p>The difference is what happens when a <strong>special character appears inside the headword itself</strong>:</p><ul><li>GoldenDict-ng inserts the headword <strong>raw</strong> into the path (<code>gdlookup://localhost/&lt;word&gt;</code>). A <code>#</code> (or <code>?</code> or <code>/</code>) inside the word becomes a fragment/query/path separator and truncates the word; its <code>gdlookup</code> + fragment branch then falls back to a fragile <code>window.location = url</code>.</li><li>Ciyue <strong>percent-encodes every byte</strong> of the headword, so <code>#</code> → <code>%23</code>, <code>/</code> → <code>%2F</code>, <code>?</code> → <code>%3F</code> never collide with URL syntax. The word round-trips intact (verified by tests such as <code>a%2Fb</code> → <code>a/b</code> and <code>%74%61%67%3A…</code> → <code>tag:sumeru</code>). Ciyue also rescues a <code>#</code> that survives in the fragment when the page script did not rewrite the link.</li></ul><p>So on the &quot;special characters inside the identifier&quot; axis, Ciyue ⊃ GoldenDict-ng.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scheme</th><th>Authored?</th><th>Stable / portable?</th><th>GD-ng</th><th>Ciyue</th></tr></thead><tbody><tr><td><code>entry://word</code></td><td>yes (MDX)</td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td><code>bword://word</code></td><td>yes (Babylon)</td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td><code>gdlookup://localhost/word</code></td><td>yes (can be hand-written)</td><td>yes (content-addressed)</td><td>yes</td><td>yes</td></tr><tr><td><code>sound://file</code></td><td>yes (MDX/Babylon)</td><td>yes</td><td>MDX loader rewrites → <code>gdau</code></td><td>yes (+ local server)</td></tr><tr><td><code>&lt;audio src=&quot;rel&quot;&gt;</code></td><td>yes</td><td>yes</td><td>StarDict loader → <code>gdau</code></td><td>yes</td></tr><tr><td><code>gdau://&lt;id&gt;/file</code></td><td>no (runtime only)</td><td>no (path-MD5 id)</td><td>yes (internal)</td><td>no (own audio mechanism)</td></tr><tr><td><code>bres</code>/<code>gico</code>/<code>gdprg</code>/<code>gdtts</code>/<code>gdinternal</code></td><td>no (runtime only)</td><td>no</td><td>yes (internal)</td><td>no (own resource mechanism)</td></tr></tbody></table><p><strong>Takeaway.</strong> To be a true superset of GoldenDict-ng at the <em>dictionary-loading</em> layer, support the de-facto authored conventions — <code>entry</code>, <code>bword</code>, <code>gdlookup://localhost/…</code>, and <code>sound://</code>. The GD-internal schemes (<code>gdau</code>, <code>bres</code>, <code>gico</code>, <code>gdprg</code>, <code>gdtts</code>, <code>gdinternal</code>) are runtime artifacts; substitute your own resource mechanism for them rather than trying to parse them.</p>',39)]))}const p=o(r,[["render",c]]);export{g as __pageData,p as default};
